import { z } from 'zod'

import { specDraftSchema } from '@/domain/spec'
import { getDb } from '@/server/db'
import { withOwner } from '@/server/http/handler'
import { readJson } from '@/server/http/problem'
import { createSpec, listSpecs } from '@/server/specs/repository'

const createSchema = specDraftSchema.extend({
  /** Generated by the client per draft, so a retried save does not create a duplicate. */
  clientId: z.uuid(),
})

export const GET = withOwner('specs.list', async (_request, { ownerId }) => {
  const specs = await listSpecs(await getDb(), ownerId)
  return Response.json({ specs }, { headers: { 'Cache-Control': 'no-store' } })
})

export const POST = withOwner('specs.create', async (request, { ownerId }) => {
  const { clientId, ...draft } = await readJson(request, createSchema)
  const { id, created } = await createSpec(await getDb(), ownerId, clientId, draft)
  return Response.json({ id }, { status: created ? 201 : 200 })
})
